[
{"type":"heading","text":"Day 1 · Fri Nov 6: Arrive + South Shore"},
{"type":"text","text":"Drive up, check in, easy lakefront walk at sunset, dinner in town. Coldest day (29–43°F), so bundle up."},
{"type":"heading","text":"Day 2 · Sat Nov 7: Emerald Bay + West Shore"},
{"type":"text","text":"Early Emerald Bay overlook and Eagle Falls hike, then drive the west shore. Warmest day (30–54°F)."},
{"type":"cards","shape":"wide","items":[
{"title":"Emerald Bay State Park","subtitle":"Overlook, Eagle Falls, shoreline views","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Emerald_Bay%2C_Lake_Tahoe%2C_California._2015.jpg/960px-Emerald_Bay%2C_Lake_Tahoe%2C_California._2015.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail","url":"https://en.wikipedia.org/wiki/Emerald_Bay_State_Park","place":"Emerald Bay State Park, CA","note":"Go before noon"},
{"title":"Vikingsholm","subtitle":"Scandinavian-style 38-room mansion","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Vikingsholmemerald.jpg/960px-Vikingsholmemerald.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail","url":"https://en.wikipedia.org/wiki/Vikingsholm","place":"Vikingsholm, Emerald Bay, CA","note":"Tours are likely closed in fall; check first"}
]},
{"type":"heading","text":"Day 3 · Sun Nov 8: Nevada side + home"},
{"type":"text","text":"Morning at the Nevada-side state park shoreline, or Heavenly if open, then head home by afternoon."},
{"type":"cards","shape":"wide","items":[
{"title":"Lake Tahoe–Nevada State Park","subtitle":"Rocky beaches, shoreline trails","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Caverock.JPG/960px-Caverock.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail","url":"https://en.wikipedia.org/wiki/Lake_Tahoe%E2%80%93Nevada_State_Park","place":"Sand Harbor, Incline Village, NV","note":"Mild day, 37–54°F"},
{"title":"Heavenly Mountain Resort","subtitle":"Gondola views, ski season opens later","image":"https://upload.wikimedia.org/wikipedia/commons/b/bd/Heavenly_Mountain_Resort_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled","url":"https://en.wikipedia.org/wiki/Heavenly_Mountain_Resort","place":"Heavenly Mountain Resort, South Lake Tahoe, CA","note":"Check operating status"}
]},
{"type":"callout","tone":"warning","text":"Friday morning may be icy on mountain roads; carry chains and check Caltrans before leaving."}
]

[
{"type":"heading","text":"Day 1 · Fri Nov 6 — Arrive & South Shore"},
{"type":"text","text":"Drive up, check in, easy evening. Coldest day (29–43°F), so keep it low-key."},
{"type":"cards","shape":"wide","items":[
{"title":"Heavenly Mountain Resort","subtitle":"Sunset views & dinner nearby","note":"Check gondola and opening status before going; ski season may not have started.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bd/Heavenly_Mountain_Resort_logo.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled","url":"https://en.wikipedia.org/wiki/Heavenly_Mountain_Resort","place":"Heavenly Mountain Resort, South Lake Tahoe"}
]},
{"type":"heading","text":"Day 2 · Sat Nov 7 — Emerald Bay"},
{"type":"text","text":"Warmest, driest day (30–54°F, 3% rain). Go in the morning for the best light."},
{"type":"cards","shape":"wide","items":[
{"title":"Emerald Bay State Park","subtitle":"Scenic overlook + Vikingsholm trail","note":"Steep ~1 mile trail down; confirm Vikingsholm tour season and parking.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Emerald_Bay%2C_Lake_Tahoe%2C_California._2015.jpg/960px-Emerald_Bay%2C_Lake_Tahoe%2C_California._2015.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail","url":"https://en.wikipedia.org/wiki/Emerald_Bay_State_Park","place":"Emerald Bay State Park, CA"},
{"title":"Vikingsholm","subtitle":"Scandinavian-style 38-room mansion","note":"Lakeside walk even if interior tours are closed.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/27/Vikingsholmemerald.jpg/960px-Vikingsholmemerald.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail","url":"https://en.wikipedia.org/wiki/Vikingsholm","place":"Vikingsholm, Tahoe"}
]},
{"type":"text","text":"Afternoon: drive the West Shore to Tahoe City for a late lunch, then dinner back in South Lake Tahoe."},
{"type":"heading","text":"Day 3 · Sun Nov 8 — East Shore & home"},
{"type":"text","text":"Mild (37–54°F). Scenic stop before the drive back to Palo Alto."},
{"type":"cards","shape":"wide","items":[
{"title":"Lake Tahoe–Nevada State Park","subtitle":"Sand Harbor / East Shore beaches & coves","note":"Short lakefront walks; check parking and fees in the off-season.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Caverock.JPG/960px-Caverock.JPG?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail","url":"https://en.wikipedia.org/wiki/Lake_Tahoe%E2%80%93Nevada_State_Park","place":"Sand Harbor, Lake Tahoe, NV"}
]},
{"type":"callout","tone":"warning","text":"Overnight lows near freezing: carry chains and check Caltrans road conditions before driving Hwy 50 or I-80."}
]
